# 🟡 中风险：会修改集群/资源状态，执行前请确认目标、影响范围与授权
# 方案 1：增加配额
kubectl patch resourcequota <quota-name> -n <namespace> -p '{
  "spec": {
    "hard": {
      "limits.cpu": "16",
      "limits.memory": "32Gi",
      "pods": "40"
    }
  }
}'

# 方案 2：清理不需要的资源
# 删除已完成的 Job
kubectl delete jobs --field-selector=status.successful=1 -n <namespace>

# 删除 Evicted Pod
kubectl delete pods --field-selector=status.phase=Failed -n <namespace>

# 方案 3：优化资源请求
# 减少不必要的资源请求
kubectl patch deployment <name> -n <namespace> -p '{
  "spec": {
    "template": {
      "spec": {
        "containers": [{
          "name": "<container>",
          "resources": {
            "requests": {"cpu": "100m", "memory": "128Mi"},
            "limits": {"cpu": "500m", "memory": "512Mi"}
          }
        }]
      }
    }
  }
}'

# 方案 4：创建新的 ResourceQuota（如需分配更多资源）
cat << EOF | kubectl apply -f -
apiVersion: v1
kind: ResourceQuota
metadata:
  name: expanded-quota
  namespace: <namespace>
spec:
  hard:
    requests.cpu: "10"
    requests.memory: "20Gi"
    limits.cpu: "20"
    limits.memory: "40Gi"
    pods: "50"
    persistentvolumeclaims: "10"
EOF

# 🟡 中风险：会修改集群/资源状态，执行前请确认目标、影响范围与授权
# 方案 1：减少资源请求
kubectl patch deployment <name> -p '{
  "spec": {
    "template": {
      "spec": {
        "containers": [{
          "name": "<container>",
          "resources": {
            "requests": {"cpu": "50m", "memory": "64Mi"}
          }
        }]
      }
    }
  }
}'

# 方案 2：扩容节点
# 使用 Cluster Autoscaler
kubectl get pods -n kube-system | grep cluster-autoscaler

# 或手动添加节点

# 方案 3：使用优先级抢占
cat << EOF | kubectl apply -f -
apiVersion: scheduling.k8s.io/v1
kind: PriorityClass
metadata:
  name: high-priority
value: 1000000
globalDefault: false
preemptionPolicy: PreemptLowerPriority
EOF

# 在 Pod 中使用
spec:
  priorityClassName: high-priority

# 方案 4：调整节点亲和性
# 从 required 改为 preferred
kubectl patch deployment <name> -p '{
  "spec": {
    "template": {
      "spec": {
        "affinity": {
          "nodeAffinity": {
            "preferredDuringSchedulingIgnoredDuringExecution": [{
              "weight": 100,
              "preference": {
                "matchExpressions": [{
                  "key": "node-type",
                  "operator": "In",
                  "values": ["compute"]
                }]
              }
            }]
          }
        }
      }
    }
  }
}'

# 🔴 高风险：可能造成数据丢失或服务中断，执行前需备份、变更审批与回滚方案
# 添加容忍
kubectl patch deployment <name> -p '{
  "spec": {
    "template": {
      "spec": {
        "tolerations": [{
          "key": "node-role.kubernetes.io/master",
          "operator": "Exists",
          "effect": "NoSchedule"
        }]
      }
    }
  }
}'

# 或移除节点污点（如果合适）
kubectl taint nodes <node-name> <taint-key>-
